create or replace function t011_full_name(
  p_first  in varchar2,
  p_middle in varchar2,
  p_last   in varchar2
) return varchar2 is
  v_full_name varchar2(4000);
begin
  v_full_name := p_first || ' ' || p_middle || ' ' || p_last;
  return trim(regexp_replace(v_full_name, '\s+', ' '));
end t011_full_name;
